import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  analyzeSource, fallbackWords, parseCanonicalSource, parseSource, readOutcome, SourceError,
} from "../src/core/source.js";

// policy-vectors.json and analyze-vectors.json are generated by the node client
// (`go test ./new/source -run 'TestPolicyVectors|TestAnalyzeVectors' -update`, docs/policy.md) and
// shared by every implementation of the source format. The SDK parses and analyzes; only nodes evaluate.
interface PolicyVectors {
  parse: {
    canonical: { name: string; input: string; canonical: string; sourceId: string }[];
    reject: { name: string; input: string; class: string }[];
  };
  eval: {
    name: string;
    source: string;
    sourceId: string;
    expect: { outcome: string; signed: { sourceId: string; value: string } | null };
  }[];
}
interface AnalyzeVectors {
  cases: { name: string; source: string; analysis: unknown }[];
}
const policy: PolicyVectors = JSON.parse(readFileSync(new URL("./policy-vectors.json", import.meta.url), "utf8"));
const analyze: AnalyzeVectors = JSON.parse(readFileSync(new URL("./analyze-vectors.json", import.meta.url), "utf8"));

describe("policy vectors", () => {
  it("has cases", () => {
    expect(policy.parse.canonical.length).toBeGreaterThan(0);
    expect(policy.parse.reject.length).toBeGreaterThan(0);
  });

  for (const v of policy.parse.canonical) {
    it(`parses ${v.name}`, () => {
      const s = parseSource(v.input);
      expect(s.canonical).toBe(v.canonical);
      expect(s.idHex).toBe(v.sourceId);
      expect(parseCanonicalSource(v.canonical).idHex).toBe(v.sourceId);
    });
  }

  for (const v of policy.parse.reject) {
    it(`rejects ${v.name}`, () => {
      let err: unknown;
      try {
        parseSource(v.input);
      } catch (e) {
        err = e;
      }
      expect(err).toBeInstanceOf(SourceError);
      expect((err as SourceError).errorClass).toBe(v.class);
    });
  }

  it("parses every eval source, and reads each signed value as the node signed it", () => {
    for (const v of policy.eval) {
      const s = parseCanonicalSource(v.source);
      expect(s.idHex, v.name).toBe(v.sourceId);
      if (!v.expect.signed) continue;
      // Every signed value is under S; an inconclusive case signs one of the source's fallback words.
      expect(v.expect.signed.sourceId, v.name).toBe(v.sourceId);
      if (v.expect.outcome === "inconclusive") {
        expect(fallbackWords(s), v.name).toContain(v.expect.signed.value);
        expect(readOutcome(v.expect.signed, s)?.kind, v.name).toBe("fallback");
      }
    }
  });
});

describe("analysis vectors", () => {
  for (const c of analyze.cases) {
    it(`analyzes ${c.name}`, () => {
      expect(JSON.parse(JSON.stringify(analyzeSource(parseCanonicalSource(c.source))))).toEqual(c.analysis);
    });
  }
});

import { cst, defineSource, eq, gte, httpInput, iff, jsonDecode, ref, strLit } from "../src/core/sourcebuild.js";

const venue = (host: string) =>
  httpInput({ url: `https://${host}/v1/ticker`, decode: jsonDecode({ px: "$.px", status: "$.status" }) });

describe("policy builders", () => {
  it("write every default", () => {
    const s = defineSource({
      inputs: { a: venue("a.example.com"), b: venue("b.example.com") },
      policy: {
        candidates: {
          a: { value: ref("a.px"), rules: [eq(ref("a.status"), strLit("open"))] },
          b: { value: ref("b.px") },
        },
      },
      transform: ref("$agg"),
      output: { type: "int256", decimals: 8 },
    });
    const p = (s.doc as any).policy;
    expect(p.combine).toEqual({ op: "median", minQualifying: "2", maxSpreadBps: null, order: null });
    expect(p.independence).toBe("distinctHosts");
    expect(p.inconclusive).toEqual({ fallback: null });
    expect(p.candidates.b).toEqual({ role: "corroborating", value: { ref: "b.px" }, weight: null, rules: [], onError: "disqualify" });
    expect(s.hasFallback).toBe(false);
    expect(s.policy?.candidates).toEqual(["a", "b"]);
  });

  it("write a fallback, and read a value as the fallback or a result", () => {
    // Reserve verdict: 1 covered, 0 short, 3 for a pending report (inconclusiveIf 0), 2 otherwise.
    const s = defineSource({
      inputs: { c: httpInput({ url: "https://custody.example.com/r", decode: jsonDecode({ bal: "$.bal", state: "$.state" }) }) },
      policy: {
        candidates: { c: { value: ref("c.bal") } },
        inconclusiveIf: [eq(ref("c.state"), strLit("pending"))],
        fallback: iff(eq(ref("$reason"), cst("16")), cst("3"), cst("2")),
      },
      transform: iff(gte(ref("$agg"), cst("1000")), cst("1"), cst("0")),
      output: { type: "uint256", decimals: 0 },
    });
    expect(s.hasFallback).toBe(true);
    const word = (n: number) => "0x" + n.toString(16).padStart(64, "0");
    expect(fallbackWords(s)).toEqual([word(2), word(3)]);
    expect(analyzeSource(s).policy?.fallback).toEqual({ values: [word(2), word(3)], reachable: false });
    expect(readOutcome({ sourceId: s.idHex, value: word(3) }, s)).toEqual({ kind: "fallback", value: word(3) });
    expect(readOutcome({ sourceId: s.idHex, value: word(1) }, s)).toEqual({ kind: "conclusive", value: word(1) });
    expect(readOutcome({ sourceId: "0x" + "22".repeat(32), value: word(2) }, s)).toBeNull();
  });
});
